fn appendI64(out:[*c]u8,at0:usize,x0:i64)usize{var at=at0;var x=x0;if(x<0){out[at]='-';at+=1;x= -x;}if(x==0){out[at]='0';return at+1;}var rev:[24]u8=undefined;var n:usize=0;while(x>0){rev[n]=@intCast('0'+@mod(x,10));n+=1;x=@divTrunc(x,10);}while(n>0){n-=1;out[at]=rev[n];at+=1;}return at;}
fn raw(out:[*c]u8,x:i64)i64{return @intCast(appendI64(out,0,x));}
fn scaled(out:[*c]u8,x:i64,scale:i64,name:[]const u8)i64{if(@rem(x,scale)!=0)return -1;var at=appendI64(out,0,@divTrunc(x,scale));for(".0 ")|c|{out[at]=c;at+=1;}for(name)|c|{out[at]=c;at+=1;}return @intCast(at);}
export fn prefix_conversions_string(v:[*c]const i64,n:usize,out:[*c]u8,cap:usize)i64{if(v==null or n!=2 or (v[0]!=0 and v[0]!=1) or v[1]< -1000000000000 or v[1]>1000000000000)return -1;if(out==null or cap<8192)return -2;const x=v[1];if(x<=0)return raw(out,x);if(v[0]==0){if(x>1000000000)return scaled(out,x,1000000000,"giga");if(x>1000000)return scaled(out,x,1000000,"mega");if(x>1000)return scaled(out,x,1000,"kilo");if(x>100)return scaled(out,x,100,"hecto");if(x>10)return scaled(out,x,10,"deca");}else{if(x>1073741824)return scaled(out,x,1073741824,"giga");if(x>1048576)return scaled(out,x,1048576,"mega");if(x>1024)return scaled(out,x,1024,"kilo");}return raw(out,x);}
